using murrty.updater;

internal static class ExecutableTrust {
    internal enum SignatureStatus { Unsigned, Valid, Invalid }
    private const uint WTD_UI_NONE = 2;
    private const uint WTD_REVOKE_NONE = 0;
    private const uint WTD_CHOICE_FILE = 1;
    private const uint WTD_STATEACTION_IGNORE = 0;
    private const uint WTD_REVOCATION_CHECK_NONE = 0x00000010;
    private const uint WTD_CACHE_ONLY_URL_RETRIEVAL = 0x00001000;
    private const uint TRUST_E_PROVIDER_UNKNOWN = 0x800B0001;
    private const uint TRUST_E_SUBJECT_FORM_UNKNOWN = 0x800B0003;
    private const uint TRUST_E_NOSIGNATURE = 0x800B0100;

    [System.Runtime.InteropServices.StructLayout(System.Runtime.InteropServices.LayoutKind.Sequential, CharSet = System.Runtime.InteropServices.CharSet.Unicode)]
    private struct WinTrustFileInfo { public uint cbStruct; public IntPtr pcwszFilePath; public IntPtr hFile; public IntPtr pgKnownSubject; }
    [System.Runtime.InteropServices.StructLayout(System.Runtime.InteropServices.LayoutKind.Sequential, CharSet = System.Runtime.InteropServices.CharSet.Unicode)]
    private struct WinTrustData { public uint cbStruct; public IntPtr pPolicyCallbackData; public IntPtr pSIPClientData; public uint dwUIChoice; public uint fdwRevocationChecks; public uint dwUnionChoice; public IntPtr pFile; public uint dwStateAction; public IntPtr hWVTStateData; public IntPtr pwszURLReference; public uint dwProvFlags; public uint dwUIContext; }
    [System.Runtime.InteropServices.DllImport("wintrust.dll", ExactSpelling = true, CharSet = System.Runtime.InteropServices.CharSet.Unicode)]
    private static extern uint WinVerifyTrust(IntPtr hwnd, ref Guid pgActionID, IntPtr pWVTData);

    internal static SignatureStatus GetStatus(string FilePath) {
        if (FilePath.IsNullEmptyWhitespace() || !File.Exists(FilePath)) return SignatureStatus.Invalid;
        IntPtr PathPointer = IntPtr.Zero, FileInfoPointer = IntPtr.Zero, TrustDataPointer = IntPtr.Zero;
        try {
            PathPointer = System.Runtime.InteropServices.Marshal.StringToCoTaskMemUni(FilePath);
            WinTrustFileInfo FileInfo = new() { cbStruct = (uint)System.Runtime.InteropServices.Marshal.SizeOf(typeof(WinTrustFileInfo)), pcwszFilePath = PathPointer };
            FileInfoPointer = System.Runtime.InteropServices.Marshal.AllocCoTaskMem(System.Runtime.InteropServices.Marshal.SizeOf(typeof(WinTrustFileInfo)));
            System.Runtime.InteropServices.Marshal.StructureToPtr(FileInfo, FileInfoPointer, false);
            WinTrustData TrustData = new() { cbStruct = (uint)System.Runtime.InteropServices.Marshal.SizeOf(typeof(WinTrustData)), dwUIChoice = WTD_UI_NONE, fdwRevocationChecks = WTD_REVOKE_NONE, dwUnionChoice = WTD_CHOICE_FILE, pFile = FileInfoPointer, dwStateAction = WTD_STATEACTION_IGNORE, dwProvFlags = WTD_REVOCATION_CHECK_NONE | WTD_CACHE_ONLY_URL_RETRIEVAL };
            TrustDataPointer = System.Runtime.InteropServices.Marshal.AllocCoTaskMem(System.Runtime.InteropServices.Marshal.SizeOf(typeof(WinTrustData)));
            System.Runtime.InteropServices.Marshal.StructureToPtr(TrustData, TrustDataPointer, false);
            Guid Action = new("00AAC56B-CD44-11d0-8CC2-00C04FC295EE");
            uint Result = WinVerifyTrust(new IntPtr(-1), ref Action, TrustDataPointer);
            if (Result == 0) return SignatureStatus.Valid;
            return Result is TRUST_E_NOSIGNATURE or TRUST_E_PROVIDER_UNKNOWN or TRUST_E_SUBJECT_FORM_UNKNOWN ? SignatureStatus.Unsigned : SignatureStatus.Invalid;
        }
        catch (Exception ex) when (ex is ArgumentException or System.Runtime.InteropServices.ExternalException or DllNotFoundException or EntryPointNotFoundException) { return SignatureStatus.Invalid; }
        finally {
            if (TrustDataPointer != IntPtr.Zero) System.Runtime.InteropServices.Marshal.FreeCoTaskMem(TrustDataPointer);
            if (FileInfoPointer != IntPtr.Zero) System.Runtime.InteropServices.Marshal.FreeCoTaskMem(FileInfoPointer);
            if (PathPointer != IntPtr.Zero) System.Runtime.InteropServices.Marshal.FreeCoTaskMem(PathPointer);
        }
    }
}

