private static bool TryParseSha256Digest(string? Value, out string Digest) {
    Digest = string.Empty;
    if (Value.IsNullEmptyWhitespace()) return false;
    string Candidate = Value!.Trim();
    if (Candidate.StartsWith("sha256:", StringComparison.OrdinalIgnoreCase)) Candidate = Candidate[7..].Trim();
    if (Candidate.Length != 64 || !Candidate.All(Uri.IsHexDigit)) return false;
    Digest = Candidate.ToLowerInvariant();
    return true;
}

private static bool TryParseSha256Checksum(string? Content, string FileName, out string Digest) {
    Digest = string.Empty;
    if (Content.IsNullEmptyWhitespace() || FileName.IsNullEmptyWhitespace()) return false;
    foreach (string RawLine in Content!.Replace("\r\n", "\n").Replace('\r', '\n').Split('\n')) {
        string Line = RawLine.Trim();
        if (Line.Length < 66) continue;
        int Separator = Line.IndexOfAny([' ', '\t']);
        if (Separator != 64 || !TryParseSha256Digest(Line[..Separator], out string Parsed)) continue;
        string Name = Line[(Separator + 1)..].TrimStart();
        if (Name.StartsWith("*", StringComparison.Ordinal)) Name = Name[1..];
        if (!Name.Equals(FileName, StringComparison.Ordinal)) continue;
        Digest = Parsed;
        return true;
    }
    return false;
}

private static bool FileMatchesSha256(string FilePath, string ExpectedHash) {
    if (!TryParseSha256Digest(ExpectedHash, out string Parsed) || !File.Exists(FilePath)) return false;
    try { return Program.CalculateSha256Hash(FilePath).Equals(Parsed, StringComparison.OrdinalIgnoreCase); }
    catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or CryptographicException) { return false; }
}

private static bool VerifyDownloadedExecutable(string FilePath, string ExpectedHash) {
    if (!FileMatchesSha256(FilePath, ExpectedHash)) return false;
    return ExecutableTrust.GetStatus(FilePath) != ExecutableTrust.SignatureStatus.Invalid;
}

